// Build Quorum heartbeat body + signing inputs (no Node crypto).
// Env: QUORUM_WORKFLOW_ID, QUORUM_KEY_ID, QUORUM_BASE_URL
// HMAC secret is used only in the Crypto HMAC node via $env.QUORUM_HMAC_SECRET.
const workflowId = $env.QUORUM_WORKFLOW_ID || 'REPLACE_QUORUM_WORKFLOW_ID';
const keyId = $env.QUORUM_KEY_ID || 'REPLACE_KEY_ID';
const baseUrl = ($env.QUORUM_BASE_URL || 'http://quorum:3000').replace(/\/+$/, '');
const path = `/api/v1/workflows/${workflowId}/heartbeats`;

const bodyObj = {
  schemaVersion: 1,
  executedAt: new Date().toISOString(),
  status: 'success',
  itemsProcessed: 1,
  externalExecutionRef: `n8n-${Date.now()}`,
};
const bodyRaw = JSON.stringify(bodyObj);
const timestampSeconds = String(Math.floor(Date.now() / 1000));
const idempotencyKey = `n8n-${timestampSeconds}-${Math.random().toString(16).slice(2)}`;

return [{
  json: {
    url: `${baseUrl}${path}`,
    path,
    bodyRaw,
    keyId,
    timestampSeconds,
    idempotencyKey,
  },
}];

// Canonical signing payload (must match Quorum heartbeat-hmac.ts):
// ["POST", path, timestampSeconds, idempotencyKey, bodySha256Hex].join("\n")
const signingPayload = [
  'POST',
  $json.path,
  $json.timestampSeconds,
  $json.idempotencyKey,
  $json.bodySha256Hex,
].join('\n');

return [{
  json: {
    ...$json,
    signingPayload,
  },
}];
